 function visible(x,y){let d=Math.hypot(x-player.x,y-player.y),steps=Math.ceil(d*8);for(let i=1;i<steps;i++){let t=i/steps;if(grid[Math.floor(player.y+(y-player.y)*t)]?.[Math.floor(player.x+(x-player.x)*t)])return false}return true}function reload(){if(ammo<kits[pick.kit][2]&&reserve>0&&!reloadTimer){reloadTimer=1.15;notify('RELOADING')}}function doPulse(){if(pulseCD>0)return;pulse=1.15;pulseCD=9;noise=1;notify('RESONANCE · SIGNAL EXPOSED');for(let p of pickups)p.reveal=5}
 function syncHUD(){$('kills').textContent=String(kills).padStart(2,'0');$('wave').textContent=String(wave).padStart(2,'0');$('hptext').textContent=Math.max(0,Math.ceil(hp));$('hpbar').style.width=Math.max(0,hp)+'%';$('ammo').innerHTML=`${ammo} <span style="color:#78877b;font-size:14px">/ ${reserve}</span>`;$('weaponname').textContent=`${kits[pick.kit][0].toUpperCase()} · ${ammo} / ${reserve}`;$('pulsetext').textContent=pulseCD>0?`Q  RESONANCE ${pulseCD.toFixed(1)}s`:'Q  RESONANCE READY'}
